style.css:
@-moz-document domain("notion.com"), domain("notion.so") {
/* Base text color - dimmed, greyish white */
.notion-page-content [class*="notranslate"] {
  color: rgba(255, 255, 255, 0.5) !important;
}

/* Page title - dimgray, like Obsidian's inline title */
.notion-page-block h1 {
  color: dimgray !important;
}

/* Bold formatting */
[style*="font-weight:600"] {
  font-weight: 700 !important;
  color: rgba(255, 255, 255, 0.7) !important;
}

/* Italic text - green */
[style*="font-style:italic"] {
  color: #7aab8a !important;
}

/* Inline links - purple */
.notion-link-token {
  color: rgba(166, 138, 249, 0.9) !important;
}

/* Inline code - brownish, dark background */
.notion-inline-code-container,
.notion-inline-code-container span {
  color: #a07848 !important;
  background-color: rgba(0, 0, 0, 0.1) !important;
}

/* --------------------------------------------------------------------------
   Headings 1-4
   Notion has 4 heading block types (Heading 1-4), unlike Obsidian's 6.
   -------------------------------------------------------------------------- */

/* Heading 1 - centered pill with purple text */
.notion-header-block {
  padding-top: 1em !important;
  padding-bottom: 1em !important;
  margin-top: 1.5em !important;
  margin-bottom: 1em !important;
  text-align: center !important;
  background-color: rgba(0, 0, 0, 0.1) !important;
  border-radius: 1em !important;
}
.notion-header-block [class*="notranslate"] {
  color: rgba(166, 138, 249, 0.8) !important;
}

/* Heading 2 - grey bar, bled to the left so its text lines up with paragraph text */
.notion-sub_header-block {
  background-color: rgba(255, 255, 255, 0.03) !important;
  padding: 0.4em 0.5em !important;
  margin-top: 1.6em !important;
  margin-bottom: 0.8em !important;
  margin-left: -8px !important;
  border-radius: 0.3em !important;
}
.notion-sub_header-block [class*="notranslate"] {
  color: #b8b8b8 !important;
}

/* Heading 3 - solid underline */
.notion-sub_sub_header-block {
  margin-top: 1.6em !important;
  margin-bottom: 0.8em !important;
  border-bottom: 3px solid rgba(255, 255, 255, 0.10) !important;
}
.notion-sub_sub_header-block [class*="notranslate"] {
  color: #b8b8b8 !important;
}

/* Heading 4 - dashed underline */
.notion-header_4-block {
  margin-top: 1.6em !important;
  margin-bottom: 0.8em !important;
  border-bottom: 2px dashed rgba(255, 255, 255, 0.10) !important;
}
.notion-header_4-block [class*="notranslate"] {
  color: #b8b8b8 !important;
}

/* Fix Notion's own native asymmetric top/bottom padding inside heading text
   wrappers (native inline style is padding-top:30px / padding-bottom:6px),
   which otherwise pushes the text off-center inside the heading block. */
.notion-header-block > div > div,
.notion-sub_header-block > div > div,
.notion-sub_sub_header-block > div > div,
.notion-header_4-block > div > div {
  padding-top: 6px !important;
}

/* --------------------------------------------------------------------------
   Divider ("---")
   -------------------------------------------------------------------------- */
.notion-divider-block {
  margin-top: 1.5em !important;
  margin-bottom: 1.5em !important;
}
.notion-divider-block > div > div {
  background-color: transparent !important;
  height: 0 !important;
  border-top: 0.25em dotted rgba(166, 138, 249, 0.5) !important;
}
}
